import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawComponentLink,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  Sel,
} from '../primitives';
import { StepInfo } from './index';
import { ComponentDef } from '../../components/types';
import { ComputationGraph } from '../../graph/types';

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

const W = 960;
const CX = W / 2;

const COLORS = {
  latent: { fill: '#ede7f6', stroke: '#4527a0' },
  time: { fill: '#fff3e0', stroke: '#e65100' },
  patch: { fill: '#e3f2fd', stroke: '#1976d2' },
  cond: { fill: '#fce4ec', stroke: '#c62828' },
  norm: { fill: '#e0f2f1', stroke: '#00897b' },
  attn: { fill: '#fce4ec', stroke: '#c62828' },
  mlp: { fill: '#f3e5f5', stroke: '#7b1fa2' },
  gate: { fill: '#fff3e0', stroke: '#e65100' },
  weight: { fill: '#f1f8e8', stroke: '#64748b' },
  out: { fill: '#e8f5e9', stroke: '#2e7d32' },
  muted: 'var(--text-muted)' as string,
};

const BOX_H = 72;
const MAT_H = 80;
const SEQ_W = 200;
const STEP_GAP = 120;
const BOX_TO_ROW = 100;
const ROW_GAP = 90;
const WEIGHT_W = 140;
const WEIGHT_H = 80;

// ═══════════════════════════════════════════════════════════════════════════════
// Helpers
// ═══════════════════════════════════════════════════════════════════════════════

interface DitStep extends StepInfo {}

function lbl(
  g: Gsel, x: number, y: number, text: string,
  opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}
): void {
  drawLabel(g as Sel, x, y, text, opts);
}
function arrowDown(g: Gsel, x: number, y1: number, y2: number, color = '#94a3b8'): void {
  drawArrow(g as Sel, x, y1, x, y2, { color });
}
function startGroup(g: Gsel, cls: string, step: number): Gsel {
  return g.append('g').attr('class', `step-node ${cls}`).attr('data-step', String(step));
}

function stepHeader(
  g: Gsel, cx: number, y: number, sn: number, title: string, formula: string,
  fill: string, stroke: string, width = 800
): number {
  const w = width;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', BOX_H)
    .attr('rx', 8).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  g.append('circle').attr('cx', cx - w / 2 + 24).attr('cy', y + BOX_H / 2)
    .attr('r', 14).attr('fill', stroke);
  lbl(g, cx - w / 2 + 24, y + BOX_H / 2 + 1, String(sn), { size: 12, weight: '700', color: '#fff' });
  lbl(g, cx - w / 2 + 48, y + BOX_H / 2 - 6, title, { size: 13, weight: '600', color: 'var(--text)', anchor: 'start' });
  lbl(g, cx - w / 2 + 48, y + BOX_H / 2 + 10, formula, { size: 9, color: 'var(--text-muted)', font: 'monospace', anchor: 'start' });
  return y + BOX_H;
}

function shapeEq(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(text.length * 6.2 + 28, 200);
  const h = 28;
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 4).attr('fill', 'var(--surface)').attr('stroke', color).attr('stroke-width', 0.5).attr('opacity', 0.9);
  lbl(g, cx, cy, text, { size: 8.5, color, font: 'monospace' });
}

function seqMatrix(
  g: Gsel, cx: number, cy: number, label: string, sub: string,
  fill: string, stroke: string, w = SEQ_W, h = MAT_H
): void {
  drawMatrixBlock(g as Sel, cx - w / 2, cy - h / 2, {
    width: w, height: h, label, sublabel: sub, fill, stroke,
    cols: 8, rows: 5, dimTop: 'S', dimRight: 'D',
  });
}

function weightMat(
  g: Gsel, cx: number, cy: number, label: string, sub: string,
  fill = COLORS.weight.fill, stroke = COLORS.weight.stroke,
  w = WEIGHT_W, h = WEIGHT_H
): void {
  drawMatrixBlock(g as Sel, cx - w / 2, cy - h / 2, {
    width: w, height: h, label, sublabel: sub, fill, stroke, cols: 5, rows: 5,
  });
}

function opCircle(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  g.append('circle').attr('cx', cx).attr('cy', cy).attr('r', 18)
    .attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 2);
  lbl(g, cx, cy + 1, text, { size: 14, weight: '700', color });
}

function badgeRect(g: Gsel, cx: number, cy: number, text: string, fill: string, stroke: string, w = 130, h = 30): void {
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  lbl(g, cx, cy + 1, text, { size: 9, weight: '600', color: stroke });
}

function paramSummary(g: Gsel, cx: number, y: number, items: string[]): number {
  const w = W - 120;
  const h = 34;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', 'var(--surface)').attr('stroke', 'var(--border)').attr('stroke-width', 0.5);
  const segW = w / items.length;
  items.forEach((item, i) => {
    lbl(g, cx - w / 2 + segW * (i + 0.5), y + h / 2 + 1, item, { size: 10, color: COLORS.muted, font: 'monospace' });
  });
  return y + h;
}

function makeStep(
  id: number, sl: string, l: string, f: string, ex: string,
  sg: string, c: string, fl: string, cl?: string[]
): DitStep {
  return { id, label: l, shortLabel: sl, formula: f, explanation: ex,
    code: { title: l, lines: cl || [`# ${f}`] }, svgGroup: sg, color: c, fill: fl };
}

/** Standard matmul row: input × weight = output, centered at cx */
function matmulRow(
  g: Gsel, cx: number, cy: number,
  inLabel: string, inSub: string, inFill: string, inStroke: string,
  wLabel: string, wSub: string, wFill: string, wStroke: string,
  outLabel: string, outSub: string, outFill: string, outStroke: string,
  inW = 160, wW = WEIGHT_W, outW = 160
): void {
  const gap = 36;
  const totalW = inW + gap + 36 + gap + wW + gap + 36 + gap + outW;
  let x = cx - totalW / 2;

  const inCx = x + inW / 2;
  seqMatrix(g, inCx, cy, inLabel, inSub, inFill, inStroke, inW, MAT_H);
  x += inW;

  const opX = x + gap / 2 + 18;
  opCircle(g, opX, cy, '×', inStroke);
  drawArrow(g as Sel, inCx + inW / 2 + 4, cy, opX - 20, cy, { color: inStroke });
  x += gap + 36;

  const wCx = x + wW / 2;
  weightMat(g, wCx, cy, wLabel, wSub, wFill, wStroke, wW, WEIGHT_H);
  drawArrow(g as Sel, opX + 20, cy, wCx - wW / 2 - 4, cy, { color: inStroke });
  x += wW;

  const eqX = x + gap / 2 + 18;
  lbl(g, eqX, cy, '=', { size: 14, weight: '700', color: '#64748b' });
  x += gap + 36;

  const outCx = x + outW / 2;
  seqMatrix(g, outCx, cy, outLabel, outSub, outFill, outStroke, outW, MAT_H);
}

// ═══════════════════════════════════════════════════════════════════════════════
// Main renderer — 6 steps
// ═══════════════════════════════════════════════════════════════════════════════

export function renderDiTArchitectureDetailed(
  g: Gsel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const nPatches = Number(params.n_patches) || 256;
  const dModel = Number(params.d_model) || 768;
  const nHeads = 12;
  const dHead = Math.floor(dModel / nHeads);
  const nBlocks = 28;
  const dFF = dModel * 4;

  const steps: DitStep[] = [];
  let stepId = 0;
  let y = 10;

  // Title
  lbl(g, CX, y + 14, 'DiT Architecture', { size: 18, weight: '700', color: 'var(--text)' });
  y += 36;
  lbl(g, CX, y + 8, 'Diffusion Transformer — predicts noise from latent patches and timestep', { size: 10, color: 'var(--text-muted)' });
  y += 28;

  y = paramSummary(g, CX, y, [
    `patches: ${nPatches}`, `d_model: ${dModel}`, `heads: ${nHeads} (d_h=${dHead})`,
    `blocks: ${nBlocks}`, `d_ff: ${dFF}`,
  ]);
  y += 28;

  // ── Step 1: Input Representations ────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-input', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Input Representations',
      `noisy latent: [${nPatches}, ${dModel}]   timestep: [${dModel}]`,
      COLORS.latent.fill, COLORS.latent.stroke);

    const rowY = h + BOX_TO_ROW;
    seqMatrix(gs, CX - 200, rowY, 'latent', `[${nPatches}, ${dModel}]`, COLORS.latent.fill, COLORS.latent.stroke);
    lbl(gs, CX - 200, rowY - MAT_H / 2 - 12, 'Noisy Latent Patches', { size: 9, color: COLORS.latent.stroke, weight: '600' });

    // Timestep (scalar embedding vector)
    const tW = 120;
    drawMatrixBlock(gs as Sel, CX + 200 - tW / 2, rowY - 20, {
      width: tW, height: 40, label: 'timestep', sublabel: `[${dModel}]`,
      fill: COLORS.time.fill, stroke: COLORS.time.stroke, cols: 6, rows: 2,
    });
    lbl(gs, CX + 200, rowY - 32, 'Timestep Embedding', { size: 9, color: COLORS.time.stroke, weight: '600' });

    shapeEq(gs, CX, rowY + MAT_H / 2 + 20,
      `latent z_t at noise level t; timestep t encoded as sinusoidal + MLP → [${dModel}]`, COLORS.latent.stroke);

    steps.push(makeStep(stepId, 'Input', 'Input Representations',
      `latent [${nPatches}, ${dModel}], timestep [${dModel}]`,
      `Noisy latent patches from the VAE encoder at noise level t, plus a timestep embedding vector.`,
      'step-input', COLORS.latent.stroke, COLORS.latent.fill));
    y = rowY + MAT_H / 2 + 20 + STEP_GAP;
  }

  // ── Step 2: Patch Embedding (Linear Projection) ──────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-patch-embed', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Patch Embedding (Linear Projection)',
      `x = latent · W_embed + b  →  [${nPatches}, ${dModel}]`,
      COLORS.patch.fill, COLORS.patch.stroke);

    arrowDown(gs, CX - 200, y, h, COLORS.latent.stroke);

    const rowY = h + BOX_TO_ROW;
    matmulRow(gs, CX, rowY,
      'latent', `[${nPatches}, ${dModel}]`, COLORS.latent.fill, COLORS.latent.stroke,
      'W_embed', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.patch.stroke,
      'x', `[${nPatches}, ${dModel}]`, COLORS.patch.fill, COLORS.patch.stroke,
      160, WEIGHT_W, 160);

    shapeEq(gs, CX, rowY + MAT_H / 2 + 24,
      `latent [${nPatches}, ${dModel}] · W_embed [${dModel}, ${dModel}] + b = x [${nPatches}, ${dModel}]`, COLORS.patch.stroke);

    steps.push(makeStep(stepId, 'Embed', 'Patch Embedding',
      `latent · W_embed → [${nPatches}, ${dModel}]`,
      'Linear projection maps noisy latent patches into the transformer\'s hidden dimension. Acts as the patch embedding layer.',
      'step-patch-embed', COLORS.patch.stroke, COLORS.patch.fill,
      [`x = latent @ W_embed + b_embed   # [${nPatches}, ${dModel}]`]));
    y = rowY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 3: Timestep Conditioning (AdaLN embedding) ──────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-timestep', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Timestep Conditioning (SiLU MLP)',
      `c = MLP(SiLU(timestep))  →  [${dModel}]  (generates scale, shift, gate)`,
      COLORS.time.fill, COLORS.time.stroke);

    arrowDown(gs, CX + 200, y, h, COLORS.time.stroke);

    // Timestep embedding MLP
    const rowY = h + BOX_TO_ROW;
    const tW = 120;
    drawMatrixBlock(gs as Sel, CX - 280 - tW / 2, rowY - 20, {
      width: tW, height: 40, label: 'timestep', sublabel: `[${dModel}]`,
      fill: COLORS.time.fill, stroke: COLORS.time.stroke, cols: 6, rows: 2,
    });

    badgeRect(gs, CX - 120, rowY, 'SiLU', COLORS.time.fill, COLORS.time.stroke);
    drawArrow(gs as Sel, CX - 280 + tW / 2 + 4, rowY, CX - 120 - 65 - 4, rowY, { color: COLORS.time.stroke });

    weightMat(gs, CX + 20, rowY, 'W_t', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.time.stroke, 110, WEIGHT_H);
    drawArrow(gs as Sel, CX - 120 + 65 + 4, rowY, CX + 20 - 55 - 4, rowY, { color: COLORS.time.stroke });

    // Condition vector output
    const condX = CX + 200;
    seqMatrix(gs, condX, rowY, 'c', `[${dModel}]`, COLORS.cond.fill, COLORS.cond.stroke, 120, MAT_H);
    drawArrow(gs as Sel, CX + 20 + 55 + 4, rowY, condX - 60 - 4, rowY, { color: COLORS.cond.stroke });

    shapeEq(gs, CX, rowY + MAT_H / 2 + 24,
      `c = SiLU(timestep) @ W_t + b  →  conditioning vector [${dModel}]`, COLORS.time.stroke);

    // Show what c generates: γ, β, α for AdaLN
    const paramY = rowY + MAT_H / 2 + 24 + ROW_GAP * 0.6;
    const paramW = 100;
    const labels = ['γ (scale)', 'β (shift)', 'α (gate)'];
    const fills = [COLORS.norm.fill, COLORS.norm.fill, COLORS.gate.fill];
    const strokes = [COLORS.norm.stroke, COLORS.norm.stroke, COLORS.gate.stroke];
    labels.forEach((lab, i) => {
      const px = CX - 160 + i * 160;
      drawMatrixBlock(gs as Sel, px - paramW / 2, paramY - 15, {
        width: paramW, height: 30, label: lab, sublabel: `[${dModel}]`,
        fill: fills[i], stroke: strokes[i], cols: 5, rows: 1,
      });
    });
    arrowDown(gs, condX, rowY + MAT_H / 2, paramY - 20, COLORS.cond.stroke);
    lbl(gs, condX + 30, paramY - 26, 'projects to:', { size: 7, color: COLORS.cond.stroke });

    shapeEq(gs, CX, paramY + 24,
      `c → γ, β (for AdaLN scale/shift) and α (for zero-init gating)`, COLORS.cond.stroke);

    steps.push(makeStep(stepId, 'Cond', 'Timestep Conditioning',
      `c = MLP(SiLU(t)) → γ, β, α`,
      `Timestep embedding produces conditioning vector c, which generates AdaLN parameters: scale (γ), shift (β), and gate (α).`,
      'step-timestep', COLORS.time.stroke, COLORS.time.fill,
      [`# Timestep conditioning via SiLU MLP`,
       `c = SiLU(timestep) @ W_t + b_t   # [${dModel}]`,
       `γ, β, α = project(c)           # scale, shift, gate`]));
    y = paramY + 24 + STEP_GAP;
  }

  // ── Step 4: AdaLN-Zero Normalization ─────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-adaln', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'AdaLN-Zero Normalization',
      `h = (1 + γ) · LayerNorm(x) + β   then   h = α ⊙ h  (zero-init gate)`,
      COLORS.norm.fill, COLORS.norm.stroke);

    arrowDown(gs, CX, y, h, COLORS.patch.stroke);

    // Sub-row A: LayerNorm
    const lnRowY = h + BOX_TO_ROW;
    seqMatrix(gs, CX - 250, lnRowY, 'x', `[${nPatches}, ${dModel}]`, COLORS.patch.fill, COLORS.patch.stroke, 150, MAT_H);
    badgeRect(gs, CX - 80, lnRowY, 'LayerNorm', COLORS.norm.fill, COLORS.norm.stroke, 140, 34);
    drawArrow(gs as Sel, CX - 250 + 75 + 4, lnRowY, CX - 80 - 70 - 4, lnRowY, { color: COLORS.norm.stroke });
    seqMatrix(gs, CX + 100, lnRowY, 'x_norm', `[${nPatches}, ${dModel}]`, COLORS.norm.fill, COLORS.norm.stroke, 160, MAT_H);
    drawArrow(gs as Sel, CX - 80 + 70 + 4, lnRowY, CX + 100 - 80 - 4, lnRowY, { color: COLORS.norm.stroke });

    shapeEq(gs, CX, lnRowY + MAT_H / 2 + 24,
      `x_norm = LayerNorm(x)  →  [${nPatches}, ${dModel}]`, COLORS.norm.stroke);

    // Sub-row B: Scale + Shift: (1+γ)·x_norm + β
    const scaleRowY = lnRowY + MAT_H / 2 + 24 + ROW_GAP;
    seqMatrix(gs, CX - 300, scaleRowY, 'x_norm', `[${nPatches}, ${dModel}]`, COLORS.norm.fill, COLORS.norm.stroke, 150, MAT_H);
    opCircle(gs, CX - 160, scaleRowY, '×', COLORS.norm.stroke);
    drawArrow(gs as Sel, CX - 300 + 75 + 4, scaleRowY, CX - 160 - 20, scaleRowY, { color: COLORS.norm.stroke });

    // (1+γ) vector
    const gammaW = 90;
    gs.append('rect').attr('x', CX - 50 - gammaW / 2).attr('y', scaleRowY - 16).attr('width', gammaW).attr('height', 32)
      .attr('rx', 4).attr('fill', COLORS.norm.fill).attr('stroke', COLORS.norm.stroke).attr('stroke-width', 1);
    lbl(gs, CX - 50, scaleRowY + 1, '(1+γ)', { size: 9, weight: '600', color: COLORS.norm.stroke });
    drawArrow(gs as Sel, CX - 50 - gammaW / 2 - 4, scaleRowY, CX - 160 + 20, scaleRowY, { color: COLORS.norm.stroke });

    opCircle(gs, CX + 50, scaleRowY, '+', COLORS.norm.stroke);
    drawArrow(gs as Sel, CX - 160 + 20, scaleRowY, CX + 50 - 20, scaleRowY, { color: COLORS.norm.stroke });

    // β vector
    const betaW = 70;
    gs.append('rect').attr('x', CX + 130 - betaW / 2).attr('y', scaleRowY - 16).attr('width', betaW).attr('height', 32)
      .attr('rx', 4).attr('fill', COLORS.norm.fill).attr('stroke', COLORS.norm.stroke).attr('stroke-width', 1);
    lbl(gs, CX + 130, scaleRowY + 1, 'β', { size: 11, weight: '700', color: COLORS.norm.stroke });
    drawArrow(gs as Sel, CX + 130 - betaW / 2 - 4, scaleRowY, CX + 50 + 20, scaleRowY, { color: COLORS.norm.stroke });

    seqMatrix(gs, CX + 280, scaleRowY, 'h_scaled', `[${nPatches}, ${dModel}]`, COLORS.norm.fill, COLORS.norm.stroke, 170, MAT_H);
    drawArrow(gs as Sel, CX + 50 + 20, scaleRowY, CX + 280 - 85 - 4, scaleRowY, { color: COLORS.norm.stroke });

    shapeEq(gs, CX, scaleRowY + MAT_H / 2 + 24,
      `h_scaled = (1+γ) · x_norm + β  →  [${nPatches}, ${dModel}]  (adaptive scale & shift)`, COLORS.norm.stroke);

    // Sub-row C: Gate (α ⊙ h_scaled)
    const gateRowY = scaleRowY + MAT_H / 2 + 24 + ROW_GAP;
    seqMatrix(gs, CX - 200, gateRowY, 'h_scaled', `[${nPatches}, ${dModel}]`, COLORS.norm.fill, COLORS.norm.stroke, 160, MAT_H);
    opCircle(gs, CX - 30, gateRowY, '⊙', COLORS.gate.stroke);
    drawArrow(gs as Sel, CX - 200 + 80 + 4, gateRowY, CX - 30 - 20, gateRowY, { color: COLORS.gate.stroke });

    const alphaW = 80;
    gs.append('rect').attr('x', CX + 70 - alphaW / 2).attr('y', gateRowY - 16).attr('width', alphaW).attr('height', 32)
      .attr('rx', 4).attr('fill', COLORS.gate.fill).attr('stroke', COLORS.gate.stroke).attr('stroke-width', 1);
    lbl(gs, CX + 70, gateRowY + 1, 'α', { size: 11, weight: '700', color: COLORS.gate.stroke });
    drawArrow(gs as Sel, CX + 70 - alphaW / 2 - 4, gateRowY, CX - 30 + 20, gateRowY, { color: COLORS.gate.stroke });
    lbl(gs, CX - 30, gateRowY - 28, 'zero-init gate', { size: 7, color: COLORS.gate.stroke, weight: '600' });

    seqMatrix(gs, CX + 230, gateRowY, 'h', `[${nPatches}, ${dModel}]`, COLORS.cond.fill, COLORS.cond.stroke, 160, MAT_H);
    drawArrow(gs as Sel, CX - 30 + 20, gateRowY, CX + 230 - 80 - 4, gateRowY, { color: COLORS.gate.stroke });

    shapeEq(gs, CX, gateRowY + MAT_H / 2 + 24,
      `h = α ⊙ h_scaled  →  [${nPatches}, ${dModel}]  (zero-init: α starts at 0, each block is identity at init)`, COLORS.gate.stroke);

    steps.push(makeStep(stepId, 'AdaLN', 'AdaLN-Zero Normalization',
      `h = α ⊙ ((1+γ)·LN(x) + β)`,
      'AdaLN-Zero: timestep-conditioned normalization with scale, shift, and a zero-initialized gate. Each DiT block starts as identity, enabling stable training of deep networks.',
      'step-adaln', COLORS.norm.stroke, COLORS.norm.fill,
      [`x_norm = LayerNorm(x)`,
       `h_scaled = (1 + γ) * x_norm + β   # adaptive scale & shift`,
       `h = α * h_scaled                  # zero-init gate (α→0 at init)`]));
    y = gateRowY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 5: DiT Transformer Block (Self-Attention + MLP) ─────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-transformer', stepId);
    const h = stepHeader(gs, CX, y, stepId, `DiT Transformer Block (×${nBlocks})`,
      `h = h + Attn(AdaLN(h))  →  h = h + MLP(AdaLN(h))  (${nHeads} heads, d_ff=${dFF})`,
      COLORS.attn.fill, COLORS.attn.stroke);

    arrowDown(gs, CX, y, h, COLORS.cond.stroke);

    // Self-Attention sub-row
    const attnLabelY = h + BOX_TO_ROW - 20;
    lbl(gs, CX, attnLabelY, 'Self-Attention Sub-layer', { size: 10, weight: '600', color: COLORS.attn.stroke });

    const attnRowY = attnLabelY + 30;
    // QKV projection (compact)
    seqMatrix(gs, CX - 300, attnRowY, 'h', `[${nPatches}, ${dModel}]`, COLORS.cond.fill, COLORS.cond.stroke, 140, MAT_H);

    // Q, K, V weight boxes
    const qkvY = attnRowY;
    weightMat(gs, CX - 140, qkvY, 'W_qkv', `[${dModel}, ${dModel * 3}]`, COLORS.weight.fill, COLORS.attn.stroke, 130, WEIGHT_H);
    drawArrow(gs as Sel, CX - 300 + 70 + 4, qkvY, CX - 140 - 65 - 4, qkvY, { color: COLORS.attn.stroke });
    opCircle(gs, CX - 220, qkvY, '×', COLORS.attn.stroke);

    seqMatrix(gs, CX + 40, qkvY, 'Q,K,V', `[${nPatches}, ${dModel}×3]`, COLORS.attn.fill, COLORS.attn.stroke, 160, MAT_H);
    drawArrow(gs as Sel, CX - 140 + 65 + 4, qkvY, CX + 40 - 80 - 4, qkvY, { color: COLORS.attn.stroke });

    shapeEq(gs, CX, qkvY + MAT_H / 2 + 24,
      `Q,K,V = h · W_qkv  →  [${nPatches}, ${dModel}] each  (${nHeads} heads, d_head=${dHead})`, COLORS.attn.stroke);

    // Attention computation
    const scoreY = qkvY + MAT_H / 2 + 24 + ROW_GAP * 0.6;
    shapeEq(gs, CX, scoreY,
      `softmax(Q · K^T / √${dHead}) · V → attn_out [${nPatches}, ${dModel}]`, COLORS.attn.stroke);

    // Output projection
    const attnOutY = scoreY + 28 + ROW_GAP * 0.6;
    seqMatrix(gs, CX - 180, attnOutY, 'attn_out', `[${nPatches}, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke, 160, MAT_H);
    weightMat(gs, CX + 10, attnOutY, 'W_o', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.attn.stroke, 100, WEIGHT_H);
    drawArrow(gs as Sel, CX - 180 + 80 + 4, attnOutY, CX + 10 - 50 - 4, attnOutY, { color: COLORS.attn.stroke });
    opCircle(gs, CX - 80, attnOutY, '×', COLORS.attn.stroke);

    seqMatrix(gs, CX + 180, attnOutY, 'attn_proj', `[${nPatches}, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke, 160, MAT_H);
    drawArrow(gs as Sel, CX + 10 + 50 + 4, attnOutY, CX + 180 - 80 - 4, attnOutY, { color: COLORS.attn.stroke });

    shapeEq(gs, CX, attnOutY + MAT_H / 2 + 24,
      `attn_proj = attn_out · W_o  →  [${nPatches}, ${dModel}]`, COLORS.attn.stroke);

    // Residual add (attention)
    const resAttnY = attnOutY + MAT_H / 2 + 24 + ROW_GAP * 0.7;
    seqMatrix(gs, CX - 150, resAttnY, 'attn_proj', `[${nPatches}, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke, 150, MAT_H);
    opCircle(gs, CX, resAttnY, '+', COLORS.out.stroke);
    drawArrow(gs as Sel, CX - 150 + 75 + 4, resAttnY, CX - 20, resAttnY, { color: COLORS.attn.stroke });
    seqMatrix(gs, CX + 150, resAttnY, 'h', `[${nPatches}, ${dModel}]`, COLORS.cond.fill, COLORS.cond.stroke, 130, MAT_H);
    lbl(gs, CX + 80, resAttnY - 16, 'residual', { size: 7, color: COLORS.cond.stroke });
    drawArrow(gs as Sel, CX + 150 - 65 - 4, resAttnY, CX + 20, resAttnY, { color: COLORS.cond.stroke });
    seqMatrix(gs, CX + 320, resAttnY, 'h\'', `[${nPatches}, ${dModel}]`, COLORS.cond.fill, COLORS.cond.stroke, 120, MAT_H);
    drawArrow(gs as Sel, CX + 20, resAttnY, CX + 320 - 60 - 4, resAttnY, { color: COLORS.out.stroke });

    shapeEq(gs, CX, resAttnY + MAT_H / 2 + 24,
      `h' = h + attn_proj  →  [${nPatches}, ${dModel}]  (residual connection)`, COLORS.out.stroke);

    // MLP sub-layer
    const mlpLabelY = resAttnY + MAT_H / 2 + 24 + ROW_GAP;
    lbl(gs, CX, mlpLabelY, 'MLP Sub-layer (Feed-Forward)', { size: 10, weight: '600', color: COLORS.mlp.stroke });

    const mlpRowY = mlpLabelY + 30;
    seqMatrix(gs, CX - 300, mlpRowY, "h'", `[${nPatches}, ${dModel}]`, COLORS.cond.fill, COLORS.cond.stroke, 140, MAT_H);
    weightMat(gs, CX - 130, mlpRowY, 'W_up', `[${dModel}, ${dFF}]`, COLORS.weight.fill, COLORS.mlp.stroke, 120, WEIGHT_H);
    drawArrow(gs as Sel, CX - 300 + 70 + 4, mlpRowY, CX - 130 - 60 - 4, mlpRowY, { color: COLORS.mlp.stroke });
    opCircle(gs, CX - 220, mlpRowY, '×', COLORS.mlp.stroke);

    badgeRect(gs, CX + 10, mlpRowY, 'GELU', COLORS.mlp.fill, COLORS.mlp.stroke, 80, 30);
    drawArrow(gs as Sel, CX - 130 + 60 + 4, mlpRowY, CX + 10 - 40 - 4, mlpRowY, { color: COLORS.mlp.stroke });

    weightMat(gs, CX + 140, mlpRowY, 'W_down', `[${dFF}, ${dModel}]`, COLORS.weight.fill, COLORS.mlp.stroke, 120, WEIGHT_H);
    drawArrow(gs as Sel, CX + 10 + 40 + 4, mlpRowY, CX + 140 - 60 - 4, mlpRowY, { color: COLORS.mlp.stroke });

    seqMatrix(gs, CX + 310, mlpRowY, 'mlp_out', `[${nPatches}, ${dModel}]`, COLORS.mlp.fill, COLORS.mlp.stroke, 160, MAT_H);
    drawArrow(gs as Sel, CX + 140 + 60 + 4, mlpRowY, CX + 310 - 80 - 4, mlpRowY, { color: COLORS.mlp.stroke });

    shapeEq(gs, CX, mlpRowY + MAT_H / 2 + 24,
      `mlp_out = GELU(h' · W_up) · W_down  →  [${nPatches}, ${dModel}]  (d_ff=${dFF})`, COLORS.mlp.stroke);

    // Residual add (MLP)
    const resMlpY = mlpRowY + MAT_H / 2 + 24 + ROW_GAP * 0.7;
    seqMatrix(gs, CX - 150, resMlpY, 'mlp_out', `[${nPatches}, ${dModel}]`, COLORS.mlp.fill, COLORS.mlp.stroke, 150, MAT_H);
    opCircle(gs, CX, resMlpY, '+', COLORS.out.stroke);
    drawArrow(gs as Sel, CX - 150 + 75 + 4, resMlpY, CX - 20, resMlpY, { color: COLORS.mlp.stroke });
    seqMatrix(gs, CX + 150, resMlpY, "h'", `[${nPatches}, ${dModel}]`, COLORS.cond.fill, COLORS.cond.stroke, 130, MAT_H);
    lbl(gs, CX + 80, resMlpY - 16, 'residual', { size: 7, color: COLORS.cond.stroke });
    drawArrow(gs as Sel, CX + 150 - 65 - 4, resMlpY, CX + 20, resMlpY, { color: COLORS.cond.stroke });
    seqMatrix(gs, CX + 320, resMlpY, 'h_out', `[${nPatches}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke, 140, MAT_H);
    drawArrow(gs as Sel, CX + 20, resMlpY, CX + 320 - 70 - 4, resMlpY, { color: COLORS.out.stroke });

    shapeEq(gs, CX, resMlpY + MAT_H / 2 + 24,
      `h_out = h' + mlp_out  →  [${nPatches}, ${dModel}]  (×${nBlocks} blocks, each with AdaLN-Zero)`, COLORS.out.stroke);

    steps.push(makeStep(stepId, 'DiT', `DiT Block (×${nBlocks})`,
      `h + Attn(AdaLN(h)) + MLP(AdaLN(h))`,
      `${nBlocks} DiT transformer blocks with AdaLN-Zero conditioning. Self-attention + MLP with pre-norm and residual connections.`,
      'step-transformer', COLORS.attn.stroke, COLORS.attn.fill,
      [`# DiT Block (×${nBlocks}), each with AdaLN-Zero`,
       `γ, β, α = timestep_proj(t)`,
       `h_norm = α * ((1+γ) * LayerNorm(h) + β)`,
       `h = h + self_attention(h_norm)   # pre-norm + residual`,
       `h_norm2 = α * ((1+γ) * LayerNorm(h) + β)`,
       `h = h + MLP(h_norm2)             # pre-norm + residual`]));
    y = resMlpY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 6: Noise Prediction Output ──────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-output', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Noise Prediction Output (Linear Head)',
      `noise_pred = h_out · W_noise + b  →  [${nPatches}, ${dModel}]`,
      COLORS.out.fill, COLORS.out.stroke);

    arrowDown(gs, CX, y, h, COLORS.out.stroke);

    const rowY = h + BOX_TO_ROW;
    matmulRow(gs, CX, rowY,
      'h_out', `[${nPatches}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke,
      'W_noise', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.out.stroke,
      'noise_pred', `[${nPatches}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke,
      160, WEIGHT_W, 170);

    shapeEq(gs, CX, rowY + MAT_H / 2 + 24,
      `noise_pred = h_out · W_noise + b  →  [${nPatches}, ${dModel}]  (predicted noise ε)`, COLORS.out.stroke);

    // Final output
    const finalY = rowY + MAT_H / 2 + 24 + ROW_GAP;
    arrowDown(gs, CX, rowY + MAT_H / 2, finalY - MAT_H / 2, COLORS.out.stroke);
    seqMatrix(gs, CX, finalY, 'ε_pred', `[${nPatches}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke, 220, MAT_H);
    lbl(gs, CX, finalY - MAT_H / 2 - 12, 'Predicted Noise', { size: 9, color: COLORS.out.stroke, weight: '600' });

    shapeEq(gs, CX, finalY + MAT_H / 2 + 24,
      `ε_pred [${nPatches}, ${dModel}] — used in diffusion sampling: z_{t-1} = f(z_t, ε_pred, t)`, COLORS.out.stroke);

    steps.push(makeStep(stepId, 'Output', 'Noise Prediction',
      `h_out · W_noise → ε_pred`,
      `Final linear projection predicts the noise added to the clean latent. Used during diffusion sampling to iteratively denoise.`,
      'step-output', COLORS.out.stroke, COLORS.out.fill,
      [`noise_pred = h_out @ W_noise + b   # [${nPatches}, ${dModel}]`,
       `# During sampling: z_{t-1} = denoise(z_t, noise_pred, t)`]));
    y = finalY + MAT_H / 2 + 24;
  }

  // ── Footer: Explanation + Component Links + Code ─────────────────────────
  y += 28;
  y = drawExplanation(g as Sel, CX - (W - 120) / 2, y, W - 120,
    'DiT (Diffusion Transformer) replaces U-Net with a pure transformer for diffusion models. ' +
    'AdaLN-Zero conditioning injects timestep information via adaptive normalization with zero-initialized gates, ' +
    `so each of the ${nBlocks} blocks starts as identity. This enables stable training of deep transformers for diffusion, ` +
    'achieving state-of-the-art FID scores (e.g., 2.7 on ImageNet 256×256 with 675M params).',
    'insight');
  y += 20;

  drawComponentLink(g as Sel, CX - (W - 120) / 2, y, (W - 120) / 2 - 8, 56, 'attention', 'Attention');
  drawComponentLink(g as Sel, CX + 8, y, (W - 120) / 2 - 8, 56, 'transformer-block', 'Transformer Block');
  y += 72;

  drawCodeAnnotation(g as Sel, CX - (W - 120) / 2, y, W - 120,
    'DiT Architecture — AdaLN-Zero (PyTorch)',
    [`Diffusion Transformer: ${nPatches} patches, d=${dModel}, ${nHeads}h, ${nBlocks} blocks`],
    [
      `class DiTBlock(nn.Module):`,
      `    def __init__(self, d_model=${dModel}, n_heads=${nHeads}):`,
      `        self.attn = MultiHeadAttention(${dModel}, ${nHeads})`,
      `        self.mlp = MLP(${dModel}, d_ff=${dFF})`,
      `        # AdaLN-Zero: zero-init gate for stable deep training`,
      ``,
      `    def adaln_zero(self, x, c):`,
      `        γ, β, α = self.cond_proj(c)  # scale, shift, gate`,
      `        h = (1 + γ) * LayerNorm(x) + β`,
      `        return α * h                   # α→0 at init`,
      ``,
      `    def forward(self, x, timestep_emb):`,
      `        x = x + self.attn(self.adaln_zero(x, timestep_emb))`,
      `        x = x + self.mlp(self.adaln_zero(x, timestep_emb))`,
      `        return x`,
      ``,
      `class DiT(nn.Module):`,
      `    def forward(self, z_t, t):`,
      `        x = self.patch_embed(z_t)      # [${nPatches}, ${dModel}]`,
      `        c = self.timestep_mlp(t)       # conditioning`,
      `        for block in self.blocks:      # ×${nBlocks}`,
      `            x = block(x, c)`,
      `        return self.noise_head(x)      # ε_pred [${nPatches}, ${dModel}]`,
    ]);

  return { width: W, height: y + 24, steps };
}
